entries[147489] = { ["name"] = "Schadensumleitung", ["text"] = "2.5% von Grundmana / 40 Energie 40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nBenötigt Schlangenstil, Ochsenstil, Tigerstil\nHeilt ein verbündetes Ziel sofort um [7 * ( 1 * ( 0.898882 * (Haupthand-Min-DPS * [0.75] 1 + 0 ) + (Angriffskraft / 14) - 1))] bis [7 * ( 1 * ( 0.898882 * (Haupthand-Max-DPS * [0.75] 1 + 0 ) + (Angriffskraft / 14) + 1))] und fügt einem Gegner innerhalb von 10 Metern 50% der Heilmenge als Naturschaden zu. Erzeugt 1 Chi." }
entries[147490] = { ["name"] = "Heilender Regen", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nRuft heilende Regenschauer herbei, die über dem gewählten Gebiet herniedergehen. Stellt bis Abbruch lang alle 5 Sek. 1824 Gesundheit von Verbündeten innerhalb des Gebiets wieder her. Befinden sich mehr als 14 Spielercharaktere (14 in 25 - Spieler - Instanzen) in diesem Bereich, wird mit jedem weiteren die Wirksamkeit der Heilung verringert." }
entries[147494] = { ["name"] = "Heilende Sphäre beschwören", ["text"] = "40 Meter Reichweite\nSofort\nBenötigt Schlangenstil, Ochsenstil, Tigerstil\nIhr bildet am Zielort 1 Min. lang eine heilende Sphäre aus heilendem Nebel. Wenn Verbündete durch sie hindurchlaufen, verbrauchen sie die Sphäre und heilen sich selbst um 9986 .\n\nEs können pro Mönch maximal 3 heilende Sphären gleichzeitig aktiv sein.\n\nWenn die Dauer der heilenden Sphäre abläuft bevor sie genutzt wurde, wird ein Verbündeter innerhalb von 6 Metern um die Sphäre um 50% ihres Effekts geheilt." }
