entries[148054] = { ["name"] = "Scharfgemacht", ["text"] = "Sofort\nWirft eine Handvoll hochentzündlicher Bomben auf die Rücken von Spielercharakteren. Nach 15 Sek. detonieren die Bomben und fügen allen Spielercharakteren im Umkreis von 9 Metern pro verbleibendem Stapel 405000 Feuerschaden zu.\n\nSpielercharaktere können 'Bombe werfen' verwenden, um eine der Bomben zu entfernen und auf den Boden fallen zu lassen. Am Boden liegende Bomben detonieren, wenn ein Spielercharakter ihnen zu nahe kommt oder selbständig nach 30 Sek. und verursachen innerhalb von 9 Metern 405000 Feuerschaden.\n\nDer Schaden dieser Bomben kann andere Bomben, die auf dem Boden liegen, entzünden und so eine Kettenreaktion auslösen." }
entries[148055] = { ["name"] = "Scharfgemacht", ["text"] = "Sofort\nWirft eine Handvoll hochentzündlicher Bomben auf die Rücken von Spielercharakteren. Nach 15 Sek. detonieren die Bomben und fügen allen Spielercharakteren im Umkreis von 9 Metern pro verbleibendem Stapel 405000 Feuerschaden zu.\n\nSpielercharaktere können 'Bombe werfen' verwenden, um eine der Bomben zu entfernen und auf den Boden fallen zu lassen. Am Boden liegende Bomben detonieren, wenn ein Spielercharakter ihnen zu nahe kommt oder selbständig nach 30 Sek. und verursachen innerhalb von 9 Metern 405000 Feuerschaden.\n\nDer Schaden dieser Bomben kann andere Bomben, die auf dem Boden liegen, entzünden und so eine Kettenreaktion auslösen." }
entries[148056] = { ["name"] = "Scharfgemacht", ["text"] = "Sofort\nWirft eine Handvoll hochentzündlicher Bomben auf die Rücken von Spielercharakteren. Nach 15 Sek. detonieren die Bomben und fügen allen Spielercharakteren im Umkreis von 9 Metern pro verbleibendem Stapel 405000 Feuerschaden zu.\n\nSpielercharaktere können 'Bombe werfen' verwenden, um eine der Bomben zu entfernen und auf den Boden fallen zu lassen. Am Boden liegende Bomben detonieren, wenn ein Spielercharakter ihnen zu nahe kommt oder selbständig nach 30 Sek. und verursachen innerhalb von 9 Metern 405000 Feuerschaden.\n\nDer Schaden dieser Bomben kann andere Bomben, die auf dem Boden liegen, entzünden und so eine Kettenreaktion auslösen." }
